using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.Animations;using LighFight.Runtime;
namespace LighFight.Editor{
// Test-only. Uses existing main runtime classes; regenerates all script references with AssetDatabase APIs.
public static class TripoRangerCandidateBuilder{
 public const string Folder="Assets/LighFight/Art/Drafts/TripoRangerPlayable";
 [Serializable]class Role{public string state,path;}[Serializable]class Roles{public Role[] roles;}[Serializable]class Contacts{public FighterView.ContactPose[] contacts;}[Serializable]class Fist{public NativeFingerPose.Joint[] joints;}
 public static void Build(){var args=Environment.GetCommandLineArgs();string modelPath=Arg(args,"-qaTargetModel",Folder+"/Source/Ranger/model.fbx");string materialPath=Arg(args,"-qaTargetMaterial",Folder+"/Source/Ranger/native-pbr.mat");BuildAt(modelPath,materialPath);}
 static string Arg(string[] a,string key,string fallback){int n=Array.IndexOf(a,key);return n>=0&&n+1<a.Length?a[n+1]:fallback;}
 public static GameObject BuildAt(string modelPath,string materialPath){Directory.CreateDirectory(Folder);var material=AssetDatabase.LoadAssetAtPath<Material>(materialPath);if(!material)throw new InvalidOperationException("Supply existing native PBR material using -qaTargetMaterial: "+materialPath);var model=AssetDatabase.LoadAssetAtPath<GameObject>(modelPath);var avatar=AssetDatabase.LoadAllAssetsAtPath(modelPath).OfType<Avatar>().Single(a=>a.isValid&&a.isHuman);var roles=JsonUtility.FromJson<Roles>(File.ReadAllText(Folder+"/candidate-roles.json")).roles.Where(r=>r.state!="sweep").ToArray();var contact=JsonUtility.FromJson<Contacts>(File.ReadAllText(Folder+"/contacts.json")).contacts.Where(c=>c.moveId!="sweep").ToArray();var controller=AssetDatabase.LoadAssetAtPath<AnimatorController>(Folder+"/candidate.controller");if(!controller)controller=AnimatorController.CreateAnimatorControllerAtPath(Folder+"/candidate.controller");var sm=controller.layers[0].stateMachine;foreach(var s in sm.states)sm.RemoveState(s.state);var clips=roles.Select(r=>new FighterView.NativeClip{state=r.state,clip=AssetDatabase.LoadAssetAtPath<AnimationClip>("Assets/LighFight/Art/Drafts/TripoPlayable/Clips/"+Path.GetFileName(r.path))}).ToArray();foreach(var entry in clips){if(!entry.clip||!entry.clip.humanMotion)throw new InvalidOperationException("Missing post-conversion human clip "+entry.state);var state=sm.AddState(entry.state);state.motion=entry.clip;state.iKOnFeet=true;if(entry.state=="Idle")sm.defaultState=state;}
 var root=new GameObject("Ranger Humanoid — test candidate (sweep disabled)");try{var rig=UnityEngine.Object.Instantiate(model,root.transform);rig.name="Native Provider Rig";rig.transform.localScale*=2;var animator=rig.GetComponent<Animator>();animator.avatar=avatar;animator.runtimeAnimatorController=controller;animator.applyRootMotion=false;animator.cullingMode=AnimatorCullingMode.AlwaysAnimate;animator.Rebind();animator.Play("Base Layer.Guard",0,0);animator.Update(0);float bottom=float.PositiveInfinity;foreach(var skin in rig.GetComponentsInChildren<SkinnedMeshRenderer>()){skin.sharedMaterials=skin.sharedMaterials.Select(m=>material).ToArray();skin.updateWhenOffscreen=true;var baked=new Mesh();skin.BakeMesh(baked,true);foreach(var v in baked.vertices)bottom=Mathf.Min(bottom,skin.transform.TransformPoint(v).y);UnityEngine.Object.DestroyImmediate(baked);}rig.transform.localPosition-=Vector3.up*bottom;
 var pose=AssetDatabase.LoadAssetAtPath<NativeFingerPose>(Folder+"/fist.asset");if(!pose){pose=ScriptableObject.CreateInstance<NativeFingerPose>();AssetDatabase.CreateAsset(pose,Folder+"/fist.asset");}pose.sourceAvatar=avatar;pose.sourceClip="Target-specific SDK human finger muscles; external thumb / folded fingers";pose.joints=JsonUtility.FromJson<Fist>(File.ReadAllText(Folder+"/fist-joints.json")).joints;if(pose.joints.Length!=30)throw new Exception("Need30 finger joints");EditorUtility.SetDirty(pose);root.AddComponent<NativeFingerPoseDriver>().Configure(animator,pose,roles.Where(r=>r.state!="palm"&&r.state!="Dance").Select(r=>r.state).ToArray());AddGrounding(root,rig);
 var view=root.AddComponent<FighterView>();view.ConfigureAnimation(animator,contact);view.UseNativeMotion(clips);view.UseSharedMaterials();foreach(var bone in rig.GetComponentsInChildren<Transform>()){if(bone==rig.transform)continue;var original=model.transform.Find(AnimationUtility.CalculateTransformPath(bone,rig.transform));if(original){bone.localPosition=original.localPosition;bone.localRotation=original.localRotation;bone.localScale=original.localScale;}}
 var prefab=PrefabUtility.SaveAsPrefabAsset(root,Folder+"/RangerHumanoidCandidate.prefab");AssetDatabase.SaveAssets();Debug.Log("AGENT_RESULT test-only candidate rebuilt; sweep absent; roles="+clips.Length+" humanAvatar="+avatar.isHuman);return prefab;}finally{UnityEngine.Object.DestroyImmediate(root);}}
 static void AddGrounding(GameObject actor,GameObject native){var skin=native.GetComponentInChildren<SkinnedMeshRenderer>();var grounding=actor.AddComponent<CandidateFootGrounding>();grounding.nativeRig=native.transform;grounding.nativeRest=native.transform.localPosition;grounding.bones=skin.bones;var supportPath=Folder+"/sole-support-native-vertex-indices.txt";var support=File.Exists(supportPath)?new HashSet<int>(File.ReadAllLines(supportPath).Where(line=>!string.IsNullOrWhiteSpace(line)).Select(int.Parse)):null;var points=new List<CandidateFootGrounding.Point>();var mesh=skin.sharedMesh;var vertices=mesh.vertices;if(support!=null&&(mesh.vertexCount!=57257||mesh.triangles.Length/3!=100000||support.Count!=134||support.Any(i=>i<0||i>=mesh.vertexCount)))throw new InvalidOperationException("Extrema support indices require verified target native mesh/importer");var binds=mesh.bindposes;using(var counts=mesh.GetBonesPerVertex())using(var weights=mesh.GetAllBoneWeights()){int offset=0;for(int v=0;v<vertices.Length;v++){float footWeight=0;var influences=new List<CandidateFootGrounding.Influence>();for(int n=0;n<counts[v];n++){var w=weights[offset+n];string name=NativeRigBones.CanonicalName(skin.bones[w.boneIndex].name);if(name.Contains("Foot")||name.Contains("Toe"))footWeight+=w.weight;influences.Add(new CandidateFootGrounding.Influence{bone=w.boneIndex,weight=w.weight,bindPoint=binds[w.boneIndex].MultiplyPoint3x4(vertices[v])});}if(support!=null?support.Contains(v):footWeight>.8f&&v%5==0)points.Add(new CandidateFootGrounding.Point{influences=influences.ToArray()});offset+=counts[v];}}grounding.shoePoints=points.ToArray();Debug.Log("Shoe proxy skin samples="+points.Count);}

}
}
